    let mut ignore_canonical: HashSet<PathBuf> = HashSet::new();
    let mut ignore_canonical_str: HashSet<String> = HashSet::new();
    for d in &ignore_dirs_raw {
        if let Ok(c) = fs::canonicalize(d) {
            ignore_canonical.insert(c.clone());
            ignore_canonical_str.insert(c.display().to_string());
        } else {
            // if cannot canonicalize, use raw path as PathBuf
            ignore_canonical.insert(PathBuf::from(d));
            ignore_canonical_str.insert(d.clone());
        }
    }
