        if let Ok(c) = fs::canonicalize(p) {
            input_canonical_set.insert(c);
        } else {
            // if symlink or nonexistent, try canonicalize parent?
            // For exemption, we should also include the path itself if it is in ignore list but passed as input
            // Use absolute path?
            if let Ok(abs) = std::fs::canonicalize(".") {
                let abs_path = if p.is_absolute() { p.clone() } else { abs.join(p) };
                // try to canonicalize as much as possible but if fails, use abs_path
                if let Ok(c) = fs::canonicalize(&abs_path) {
                    input_canonical_set.insert(c);
                } else {
                    input_canonical_set.insert(abs_path);
                }
