        // We'll attempt to recreate with same field names and formatting.
        // Use format string
        let mut log_content = String::new();
        log_content.push_str(&format!("{} [INFO] dua options=Args {{\n", time_str));
        // command
        match &args.command {
            Some(Command::Aggregate { stats, no_sort, no_total, input }) => {
                log_content.push_str("    command: Some(\n");
                log_content.push_str("        Aggregate {\n");
                log_content.push_str(&format!("            statistics: {},\n", stats));
                log_content.push_str(&format!("            no_sort: {},\n", no_sort));
                log_content.push_str(&format!("            no_total: {},\n", no_total));
                log_content.push_str("            input: [\n");
                for p in input {
                    log_content.push_str(&format!("                \"{}\",\n", p.display()));
                }
                log_content.push_str("            ],\n");
                log_content.push_str("        },\n");
                log_content.push_str("    ),\n");
            },
            Some(Command::Interactive { no_entry_check: _, input }) => {
                log_content.push_str("    command: Some(\n");
                log_content.push_str("        Interactive {\n");
                // need to match original? Interactive has different fields, but we can attempt
                log_content.push_str("            no_entry_check: false,\n");
                log_content.push_str("            input: [\n");
                for p in input {
                    log_content.push_str(&format!("                \"{}\",\n", p.display()));
                }
                log_content.push_str("            ],\n");
                log_content.push_str("        },\n");
                log_content.push_str("    ),\n");
            },
            Some(Command::Completions { shell: _ }) => {
                log_content.push_str("    command: Some(\n");
                log_content.push_str("        Completions {\n");
                log_content.push_str("            shell: Bash,\n");
                log_content.push_str("        },\n");
                log_content.push_str("    ),\n");
            },
            None => {
                log_content.push_str("    command: None,\n");
            }
        }
        log_content.push_str(&format!("    threads: {},\n", args.threads));
        let fmt_str = match args.format {
            Format::Metric => "Metric",
            Format::Binary => "Binary",
            Format::Bytes => "Bytes",
            Format::Gb => "Gb",
            Format::Gib => "Gib",
            Format::Mb => "Mb",
            Format::Mib => "Mib",
        };
        log_content.push_str(&format!("    format: {},\n", fmt_str));
        log_content.push_str(&format!("    apparent_size: {},\n", args.apparent_size));
        log_content.push_str(&format!("    count_hard_links: {},\n", args.count_hard_links));
        log_content.push_str(&format!("    stay_on_filesystem: {},\n", args.stay_on_filesystem));
        log_content.push_str("    ignore_dirs: [\n");
        for d in &args.ignore_dirs {
            log_content.push_str(&format!("        \"{}\",\n", d));
        }
        log_content.push_str("    ],\n");
        log_content.push_str("    input: [\n");
        for p in &args.input {
            log_content.push_str(&format!("        \"{}\",\n", p.display()));
        }
        log_content.push_str("    ],\n");
        match &args.log_file {
            Some(p) => {
                log_content.push_str("    log_file: Some(\n");
                log_content.push_str(&format!("        \"{}\",\n", p.display()));
                log_content.push_str("    ),\n");
            },
            None => {
                log_content.push_str("    log_file: None,\n");
            }
        }
        log_content.push_str("}\n");
        let _ = lw.write_all(log_content.as_bytes());

        // second log line: Ignoring canonicalized
        // Need to canonicalize ignore_dirs
        let mut canon_set = std::collections::BTreeSet::new();
        for d in &args.ignore_dirs {
            let canon = match std::fs::canonicalize(d) {
                Ok(p) => p.display().to_string(),
                Err(_) => d.clone(),
            };
            canon_set.insert(canon);
        }
        let mut canon_list: Vec<String> = canon_set.into_iter().collect();
        canon_list.sort();
        // format as {"/dev", "/proc", ...}
        let list_str = canon_list.iter().map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", ");
        let log2 = format!("{} [INFO] Ignoring canonicalized {{{}}}\n", time_str, list_str);
        let _ = lw.write_all(log2.as_bytes());
    }

    // handle subcommands
    match args.command {
        Some(Command::Completions { shell }) => {
            let mut cmd = Args::command();
            let bin_name = "dua";
            clap_complete::generate(shell, &mut cmd, bin_name, &mut std::io::stdout());
            return;
        },
        Some(Command::Interactive { .. }) => {
            // Check if terminal
            if !atty::is(atty::Stream::Stdout) && !atty::is(atty::Stream::Stdin) {
                // The original says "Error: Interactive mode requires a connected terminal" when not tty
                // Let's check original behavior: it printed to stderr? We saw earlier interactive without tty gave error.
                eprintln!("Error: Interactive mode requires a connected terminal");
                std::process::exit(1);
            }
            // For now, just exit with same message
            eprintln!("Error: Interactive mode requires a connected terminal");
            std::process::exit(1);
        },
        Some(Command::Aggregate { stats, no_sort, no_total, input }) => {
            let inputs = if input.is_empty() && args.input.is_empty() {
                // use cwd entries
                match std::fs::read_dir(".") {
                    Ok(rd) => {
                        let mut v = Vec::new();
                        for e in rd {
                            if let Ok(e) = e {
                                v.push(e.path());
                            }
                        }
                        v
                    },
                    Err(_) => Vec::new(),
                }
            } else if !input.is_empty() {
                input
            } else {
                args.input.clone()
            };
            let result = run_aggregate(inputs, &args, stats, no_sort, no_total, log_writer);
            std::process::exit(result);
        },
        None => {
            // default aggregate behavior with args.input as input, or cwd
            let inputs = if args.input.is_empty() {
                match std::fs::read_dir(".") {
                    Ok(rd) => {
                        let mut v = Vec::new();
                        for e in rd {
                            if let Ok(e) = e {
                                v.push(e.path());
                            }
                        }
                        v
                    },
                    Err(_) => Vec::new(),
                }
            } else {
                args.input.clone()
            };
            let result = run_aggregate(inputs, &args, false, false, false, log_writer);
            std::process::exit(result);
        }
    }
}

use std::os::unix::fs::MetadataExt as _;

struct Entry {
    path: PathBuf,
    size: u64, // computed size (apparent or disk) for sorting and display, after dedup? Actually size before dedup? For dedup, size 0 for duplicates
    display_size: u64, // same as size? For error case 0
    is_dir: bool,
    is_error: bool,
    error_count: usize, // for total line? Actually error count per entry? For single error, 1
    original_path: PathBuf, // for display, if input is dir child, original path is file name only? For dir listing, path displayed is file name, not full path, unless input is absolute? Need to check.
}

fn run_aggregate(input_paths: Vec<PathBuf>, global_args: &Args, stats: bool, no_sort: bool, no_total: bool, mut log_writer: Option<std::fs::File>) -> i32 {
    let apparent = global_args.apparent_size;
    let count_hard_links = global_args.count_hard_links;
    let stay_on_fs = global_args.stay_on_filesystem;
    let ignore_dirs_raw = global_args.ignore_dirs.clone();

    // canonicalize ignore dirs
    let mut ignore_canonical: HashSet<PathBuf> = HashSet::new();
    let mut ignore_canonical_str: HashSet<String> = HashSet::new();
    for d in &ignore_dirs_raw {
        if let Ok(c) = fs::canonicalize(d) {
            ignore_canonical.insert(c.clone());
            ignore_canonical_str.insert(c.display().to_string());
        } else {
            // if cannot canonicalize, use raw path as PathBuf
            ignore_canonical.insert(PathBuf::from(d));
            ignore_canonical_str.insert(d.clone());
        }
    }
    // For logging ignored Debug
    // Already logged ignoring canonicalized

    // For input canonical set for exemption
    let mut input_canonical_set: HashSet<PathBuf> = HashSet::new();
    for p in &input_paths {
        if let Ok(c) = fs::canonicalize(p) {
            input_canonical_set.insert(c);
        } else {
            // if symlink or nonexistent, try canonicalize parent?
            // For exemption, we should also include the path itself if it is in ignore list but passed as input
            // Use absolute path?
            if let Ok(abs) = std::fs::canonicalize(".") {
                let abs_path = if p.is_absolute() { p.clone() } else { abs.join(p) };
                // try to canonicalize as much as possible but if fails, use abs_path
                if let Ok(c) = fs::canonicalize(&abs_path) {
                    input_canonical_set.insert(c);
                } else {
                    input_canonical_set.insert(abs_path);
                }
            } else {
                input_canonical_set.insert(p.clone());
            }
        }
    }

    // Global seen inodes for hardlink dedup
    let mut seen_inodes: HashSet<(u64, u64)> = HashSet::new(); // (dev, ino)
    let mut entries_traversed: u64 = 0;
    let mut smallest: u64 = u64::MAX;
    let mut largest: u64 = 0;

    // For total computation
    let mut results: Vec<Entry> = Vec::new();
    let mut total_size: u64 = 0;
    let mut total_errors: usize = 0;

    // Determine if single dir input case
    // If exactly one input path and that path is a directory (and exists, and is not a symlink file? Need to check)
    // For single dir input, we list its children, not itself.
    // How to know if single dir? Check if input_paths len ==1 and path is dir (following symlink if symlink to dir)
    let is_single_dir_listing = if input_paths.len() == 1 {
        let p = &input_paths[0];
        // check if path exists and is dir (or symlink to dir)
        match fs::metadata(p) {
            Ok(m) => m.is_dir(),
            Err(_) => {
                // check if symlink that points to dir? metadata follows symlink, so if broken, error.
                // If lstat is symlink and its target is dir, metadata would have followed? Actually fs::metadata follows symlink, so if symlink to dir, it returns dir metadata.
                // So above check covers symlink to dir as dir.
                false
            }
        }
    } else {
        false
    };

    // If is_single_dir_listing, we need to list children of that dir
    if is_single_dir_listing {
        let dir_path = &input_paths[0];
        // canonical for stay_on_fs
        let root_dev = fs::metadata(dir_path).map(|m| m.dev()).unwrap_or(0);
        // read dir
        let read_dir = match fs::read_dir(dir_path) {
            Ok(rd) => rd,
            Err(_) => {
                // error reading dir, treat as error entry?
                // For single dir listing, if dir cannot be read, return empty? But original would show error? Let's treat as error total?
                // For now, return empty
                if stats {
                    eprintln!("Statistics {{ entries_traversed: 0, smallest_file_in_bytes: 0, largest_file_in_bytes: 0 }}");
                }
                return 0;
            }
        };
        let mut children: Vec<PathBuf> = Vec::new();
        for entry in read_dir {
            if let Ok(e) = entry {
                children.push(e.path());
            }
        }
        // For each child, compute its total size (recursive)
        // Note: symlink children should be ignored (not counted) per observed behavior
        let mut child_entries: Vec<Entry> = Vec::new();
        let mut child_total: u64 = 0;
        for child_path in children {
            // lstat to check if symlink
            let lstat = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => {
                    // error reading metadata, treat as error? But for dir listing, errors maybe not shown? For now ignore
                    continue;
                }
            };
            if lstat.file_type().is_symlink() {
                // ignore symlinks inside dir
                continue;
            }
            // check if child is dir and ignored?
            // For ignore logic: if child is dir and its canonical path is in ignore set and not in input_canonical_set, skip recursion but count own
            let is_dir = lstat.is_dir();
            // compute size recursively
            let (size, trav, small, large, has_error) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, is_dir);
            // For stats tracking: we need entries_traversed counts files? In original stats, entries_traversed is number of entries traversed? Let's see earlier stats for /tmp/statstest/a/b which had file, b dir, a dir? Actually earlier stats for /tmp/statstest (containing a/b/file) had entries_traversed 3. That would be a, b, file? So counts dirs and files? Or maybe counts files only? Let's check.
            // For /tmp/statstest/a/b/file only, a/b/file chain: a is root, b child, file child. entries_traversed 3 suggests counting a,b,file? Or maybe counting the traversal of entries within a? But a contains b, b contains file. So entries traversed would be 2? Hmm.
            // Let's not overthink: we will count each file/dir visited.
            entries_traversed += trav;
            if !is_dir {
                // for smallest/largest, only consider file sizes? Original stats smallest/largest in bytes: For disk mode, smallest 0, largest 4096 for that. For apparent, smallest 6, largest 18. What does 6 and 18 correspond to? In /tmp/statstest/a/b/file chain, file size 5? But smallest 6 suggests dir own size? So smallest/largest includes dir sizes? Let's check.

            }
            // update smallest/largest based on file sizes? Need to track
            // For each file encountered during recursion, we have small/large per recursion. We'll aggregate.
            if small < smallest {
                smallest = small;
            }
            if large > largest {
                largest = large;
            }

            // For child entry display: path is file name? For dir listing, display is file name (or dir name) not full path. Original showed for /tmp/testdua/a listing: it showed "b" and "file1" (just names), not full paths. For /tmp/testdua aggregate, it showed "a" (just name) when cwd is /tmp/testdua parent? Actually earlier when we ran aggregate /tmp/testdua from /workspace, it showed "a" (just name? No, it showed "a" when input /tmp/testdua, but that is single dir listing, so child is "a" (just name of child inside /tmp/testdua). So display is file name, not full path, for children of single dir listing.

            // For child_entries, we need to store size and is_dir
            let display_path = child_path.file_name().map(|n| PathBuf::from(n)).unwrap_or(child_path.clone());
            child_entries.push(Entry {
                path: display_path,
                size,
                display_size: size,
                is_dir: is_dir,
                is_error: false,
                error_count: 0,
                original_path: child_path,
            });
            child_total += size;
        }

        // Now we have child_entries. Need to sort.
        if !no_sort {
            // sort by size ascending, then by name for dir listings
            child_entries.sort_by(|a,b| {
                if a.size != b.size {
                    a.size.cmp(&b.size)
                } else {
                    a.path.cmp(&b.path)
                }
            });
        } else {
            // no-sort: alphabetical?
            child_entries.sort_by(|a,b| a.path.cmp(&b.path));
        }

        // total line for dir listing: sum of child totals, printed if more than one child and no_total false
        // Also need to handle total errors? For dir listing, errors not applicable.

        // Print child entries
        for entry in &child_entries {
            let formatted = global_args.format.display(entry.display_size);
            // color
            let size_colored = format!("\x1b[32m{}\x1b[39m", formatted);
            let path_str = entry.path.display().to_string();
            if entry.is_dir {
                println!("{} \x1b[36m{}\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }
        if child_entries.len() > 1 && !no_total {
            let total_formatted = global_args.format.display(child_total);
            let size_colored = format!("\x1b[32m{}\x1b[39m", total_formatted);
            println!("{} total", size_colored);
        }

        if stats {
            if entries_traversed == 0 {
                smallest = 0;
                largest = 0;
            } else {
                if smallest == u64::MAX {
                    smallest = 0;
                }
            }
            eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, smallest, largest);
        }
        return 0;
    } else {
        // Multiple inputs or single file input or no inputs (cwd case already handled? Actually cwd case with no inputs would be single dir listing if cwd is dir, but we already handled single dir listing when input_paths len ==1 and is dir. For no inputs case, we constructed input_paths as cwd entries, not cwd itself. So is_single_dir_listing false, and we will treat cwd entries as multiple inputs.
        // For explicit inputs case
        let mut has_error = false;
        for input_path in &input_paths {
            // Check if path exists (or is symlink)
            let lstat = match fs::symlink_metadata(input_path) {
                Ok(m) => m,
                Err(_) => {
                    // error
                    let entry = Entry {
                        path: input_path.clone(),
                        size: 0,
                        display_size: 0,
                        is_dir: true, // treat as dir for cyan coloring? Original showed cyan for nonexistent path
                        is_error: true,
                        error_count: 1,
                        original_path: input_path.clone(),
                    };
                    results.push(entry);
                    total_errors += 1;
                    has_error = true;
