fn compute_size_recursive(
    path: &Path,
    apparent: bool,
    count_hard_links: bool,
    stay_on_fs: bool,
    ignore_canonical: &HashSet<PathBuf>,
    input_canonical_set: &HashSet<PathBuf>,
    seen_inodes: &mut HashSet<(u64, u64)>,
    root_dev: u64,
    log_writer: &mut Option<std::fs::File>,
    is_root_dir: bool,
) -> (u64, u64, u64, u64, bool) {
    // returns (size, entries_traversed, smallest, largest, has_error)
    // For file: size = apparent or disk, entries=1, smallest=largest=size
    // For dir: size = own + sum(children), entries = sum + maybe 1? Need to define.

    // First, lstat
    let lstat = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => {
            return (0, 0, u64::MAX, 0, true);
        }
    };
    if lstat.file_type().is_symlink() {
        // For explicit dir symlink case, we call this function with is_root_dir true and path is symlink to dir.
        // We should follow symlink to dir and compute its contents, but not count symlink itself.
        // For file symlink, we already handled in caller.
        // So here, if path is symlink and is dir (followed), we should stat the target and compute.
        if let Ok(meta) = fs::metadata(path) {
            if meta.is_dir() {
                // treat as dir, but own size? What is own size for symlink to dir?
                // For apparent, symlink to dir's own? In earlier test, symlink to dir total included real dir's own, not symlink's own.
                // So we should compute size of target dir, including its own.
                // We'll get target dir's metadata
                let target_path = fs::canonicalize(path).unwrap_or(path.to_path_buf());
                // check ignore
                if ignore_canonical.contains(&target_path) && !input_canonical_set.contains(&target_path) {
                    // ignored: count own only?
                    // For symlink to dir that is ignored, what size? Should be target dir's own? Let's return own.
                    let own_size = if apparent { meta.size() } else { meta.blocks()*512 };
                    return (own_size, 1, own_size, own_size, false);
                }
                // Recurse into target dir's entries, but using target_path as base? Actually we need to read dir entries of the symlink path (which will list target's entries)
                let mut total_size = if apparent { meta.size() } else { meta.blocks()*512 };
                let mut entries = 1;
                let mut smallest = total_size;
                let mut largest = total_size;
                let mut has_error = false;
                // read dir via path (symlink path works)
                let rd = match fs::read_dir(path) {
                    Ok(rd) => rd,
                    Err(_) => return (total_size, entries, smallest, largest, true),
                };
                for entry in rd {
                    if let Ok(e) = entry {
                        let child_path = e.path();
                        // lstat child
                        let child_lstat = match fs::symlink_metadata(&child_path) {
                            Ok(m) => m,
                            Err(_) => continue,
                        };
                        if child_lstat.file_type().is_symlink() {
                            continue;
                        }
                        let child_is_dir = child_lstat.is_dir();
                        // check ignore for child dir
                        if child_is_dir {
                            let child_canon = fs::canonicalize(&child_path).unwrap_or(child_path.clone());
                            if ignore_canonical.contains(&child_canon) && !input_canonical_set.contains(&child_canon) {
                                // log debug if needed
                                if let Some(ref mut lw) = log_writer {
                                    use std::io::Write;
                                    let now = chrono::Local::now();
                                    let time_str = now.format("%H:%M:%S").to_string();
                                    let msg = format!("{} [DEBUG] (1) dua::common: Ignored \"{}\"\n", time_str, child_path.display());
                                    let _ = lw.write_all(msg.as_bytes());
                                }
                                // count own size only
                                let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                                total_size += own;
                                entries += 1;
                                if own < smallest { smallest = own; }
                                if own > largest { largest = own; }
                                continue;
                            }
                            // stay on fs
                            if stay_on_fs && child_lstat.dev() != root_dev {
                                let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                                total_size += own;
                                entries += 1;
                                if own < smallest { smallest = own; }
                                if own > largest { largest = own; }
                                continue;
                            }
                        }
                        // recurse
                        let (child_size, child_entries, child_small, child_large, _child_err) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, ignore_canonical, input_canonical_set, seen_inodes, root_dev, log_writer, false);
                        total_size += child_size;
                        entries += child_entries;
                        if child_small < smallest { smallest = child_small; }
                        if child_large > largest { largest = child_large; }
                    }
                }
                return (total_size, entries, smallest, largest, has_error);
            }
        }
        // if not dir or broken, return 0
        return (0, 0, u64::MAX, 0, true);
    }

    if !lstat.is_dir() {
        // file
        let dev = lstat.dev();
        let ino = lstat.ino();
        let nlink = lstat.nlink();
        let size = if apparent { lstat.size() } else { lstat.blocks()*512 };
        // deduplication
        if !count_hard_links && nlink > 1 {
            if seen_inodes.contains(&(dev, ino)) {
                return (0, 1, 0, 0, false);
            } else {
                seen_inodes.insert((dev, ino));
            }
        }
        return (size, 1, size, size, false);
    }

    // dir
    // check if dir itself is ignored and not input
    let canon = fs::canonicalize(path).unwrap_or(path.to_path_buf());
    if !is_root_dir && ignore_canonical.contains(&canon) && !input_canonical_set.contains(&canon) {
        if let Some(ref mut lw) = log_writer {
            use std::io::Write;
            let now = chrono::Local::now();
            let time_str = now.format("%H:%M:%S").to_string();
            let msg = format!("{} [DEBUG] (1) dua::common: Ignored \"{}\"\n", time_str, path.display());
            let _ = lw.write_all(msg.as_bytes());
        }
        let own_size = if apparent { lstat.size() } else { lstat.blocks()*512 };
        return (own_size, 1, own_size, own_size, false);
    }

    // stay on fs: if dir's dev != root_dev and not root, treat as ignored (own only)
    if !is_root_dir && stay_on_fs && lstat.dev() != root_dev {
        let own_size = if apparent { lstat.size() } else { lstat.blocks()*512 };
        return (own_size, 1, own_size, own_size, false);
    }

    let own_size = if apparent { lstat.size() } else { lstat.blocks()*512 };
    let mut total = own_size;
    let mut entries = 1;
    let mut smallest = own_size;
    let mut largest = own_size;
    let mut has_error = false;

    // For dir dedup: if dir inode already seen and nlink>1, should we count own 0? Let's see duplicate dir path gave own 0 second time. So dir dedup based on inode.
    let dev = lstat.dev();
    let ino = lstat.ino();
    let nlink = lstat.nlink();
    if !is_root_dir && !count_hard_links && nlink > 1 {
        if seen_inodes.contains(&(dev, ino)) {
            // dir already seen, count 0 for own? But we already added own. Should return 0?
            // For duplicate dir path, second dir total was file only, not 0, so dir own 0 but file recounted. So we should not return 0 entirely, but own 0 and still traverse children?
            // For now, if dir seen, set own to 0 but still traverse? Let's see.
            // In duplicate dir case with single file nlink 1, second dir total 5 = file only, own 0. So own deduped to 0, but file recounted.
            // So we should set total = 0 initially, not own, and still traverse children.
            // Let's handle: if dir seen, own not counted.
            total = 0;
            // But we still need to track smallest/largest? For own deduped, smallest/largest should be based on children only?
            smallest = u64::MAX;
            largest = 0;
        } else {
            seen_inodes.insert((dev, ino));
        }
    } else {
        // For root dir, we don't dedup own? Actually root dir own not included in total for dir listing, but for explicit dir total it is included. For recursion, we add own.
        // For nlink check, for dir we should still insert into seen?
        if !count_hard_links {
            seen_inodes.insert((dev, ino));
        }
    }

    // read dir
    let rd = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(_) => return (total, entries, smallest, largest, true),
    };

    for entry in rd {
        if let Ok(e) = entry {
            let child_path = e.path();
            let child_lstat = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if child_lstat.file_type().is_symlink() {
                continue;
            }
            let child_is_dir = child_lstat.is_dir();
            if child_is_dir {
                let child_canon = fs::canonicalize(&child_path).unwrap_or(child_path.clone());
                if ignore_canonical.contains(&child_canon) && !input_canonical_set.contains(&child_canon) {
                    if let Some(ref mut lw) = log_writer {
                        use std::io::Write;
                        let now = chrono::Local::now();
                        let time_str = now.format("%H:%M:%S").to_string();
                        let msg = format!("{} [DEBUG] (1) dua::common: Ignored \"{}\"\n", time_str, child_path.display());
                        let _ = lw.write_all(msg.as_bytes());
                    }
                    let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                    total += own;
                    entries += 1;
                    if own < smallest { smallest = own; }
                    if own > largest { largest = own; }
                    continue;
                }
                if stay_on_fs && child_lstat.dev() != root_dev {
                    let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                    total += own;
                    entries += 1;
                    if own < smallest { smallest = own; }
                    if own > largest { largest = own; }
                    continue;
                }
            }
            let (child_size, child_entries, child_small, child_large, _child_err) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, ignore_canonical, input_canonical_set, seen_inodes, root_dev, log_writer, false);
            total += child_size;
            entries += child_entries;
            if child_small < smallest { smallest = child_small; }
            if child_large > largest { largest = child_large; }
        }
    }

    if smallest == u64::MAX {
        smallest = own_size;
    }

    (total, entries, smallest, largest, has_error)
}
