use std::path::{PathBuf, Path};
use std::collections::{HashSet, HashMap};
use std::os::unix::fs::MetadataExt;
use clap::{Parser, Subcommand, ValueEnum};
use std::fs;

#[derive(ValueEnum, Clone, Debug, PartialEq)]
enum Format {
    #[value(name = "metric")]
    Metric,
    #[value(name = "binary")]
    Binary,
    #[value(name = "bytes")]
    Bytes,
    #[value(name = "gb")]
    Gb,
    #[value(name = "gib")]
    Gib,
    #[value(name = "mb")]
    Mb,
    #[value(name = "mib")]
    Mib,
}

impl Format {
    fn display(&self, bytes: u64) -> String {
        match self {
            Format::Bytes => format!("{:10} b", bytes),
            Format::Binary => {
                if bytes <= 1024 {
                    format!("{:7}   B", bytes)
                } else if bytes <= 1024*1024 {
                    let v = bytes as f64 / 1024.0;
                    format!("{:7.2} KiB", v)
                } else if bytes <= 1024*1024*1024 {
                    let v = bytes as f64 / (1024.0*1024.0);
                    format!("{:7.2} MiB", v)
                } else if bytes <= 1024u64*1024*1024*1024 {
                    let v = bytes as f64 / (1024.0*1024.0*1024.0);
                    format!("{:7.2} GiB", v)
                } else if bytes <= 1024u64*1024*1024*1024*1024 {
                    let v = bytes as f64 / (1024.0*1024.0*1024.0*1024.0);
                    format!("{:7.2} TiB", v)
                } else if bytes <= 1024u64*1024*1024*1024*1024*1024 {
                    let v = bytes as f64 / (1024.0*1024.0*1024.0*1024.0*1024.0);
                    format!("{:7.2} PiB", v)
                } else {
                    let v = bytes as f64 / (1024.0*1024.0*1024.0*1024.0*1024.0*1024.0);
                    format!("{:7.2} EiB", v)
                }
            },
            Format::Metric => {
                if bytes <= 1000 {
                    format!("{:6}  B", bytes)
                } else if bytes <= 1000*1000 {
                    let v = bytes as f64 / 1000.0;
                    format!("{:6.2} KB", v)
                } else if bytes <= 1000*1000*1000 {
                    let v = bytes as f64 / (1000.0*1000.0);
                    format!("{:6.2} MB", v)
                } else if bytes <= 1000u64*1000*1000*1000 {
                    let v = bytes as f64 / (1000.0*1000.0*1000.0);
                    format!("{:6.2} GB", v)
                } else if bytes <= 1000u64*1000*1000*1000*1000 {
                    let v = bytes as f64 / (1000.0*1000.0*1000.0*1000.0);
                    format!("{:6.2} TB", v)
                } else {
                    let v = bytes as f64 / (1000.0*1000.0*1000.0*1000.0*1000.0);
                    format!("{:6.2} PB", v)
                }
            },
            Format::Gb => {
                let v = bytes as f64 / 1_000_000_000.0;
                format!("{:7.2} GB", v)
            },
            Format::Gib => {
                let v = bytes as f64 / (1024.0*1024.0*1024.0);
                format!("{:6.2} GiB", v)
            },
            Format::Mb => {
                let v = bytes as f64 / 1_000_000.0;
                format!("{:9.2} MB", v)
            },
            Format::Mib => {
                let v = bytes as f64 / (1024.0*1024.0);
                format!("{:8.2} MiB", v)
            },
        }
    }
}

#[derive(Parser, Debug)]
#[command(name = "dua", version = "2.32.2", about = "A tool to learn about disk usage, fast!")]
struct Args {
    #[command(subcommand)]
    command: Option<Command>,

    #[arg(short='t', long="threads", default_value="0", help="The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")]
    threads: usize,

    #[arg(short='f', long="format", default_value="binary", value_enum, help="The format with which to print byte counts")]
    format: Format,

    #[arg(short='A', long="apparent-size", help="Display apparent size instead of disk usage")]
    apparent_size: bool,

    #[arg(short='l', long="count-hard-links", help="Count hard-linked files each time they are seen")]
    count_hard_links: bool,

    #[arg(short='x', long="stay-on-filesystem", help="If set, we will not cross filesystems or traverse mount points")]
    stay_on_filesystem: bool,

    #[arg(short='i', long="ignore-dirs", default_values_t = vec!["/proc".to_string(), "/dev".to_string(), "/sys".to_string(), "/run".to_string()], help="One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.\n\nHence, they will only be ignored if they are eventually reached as part of the traversal.")]
    ignore_dirs: Vec<String>,

    #[arg(long="log-file", help="Write a log file with debug information, including panics")]
    log_file: Option<PathBuf>,

    #[arg(value_name = "INPUT", help="One or more input files or directories. If unset, we will use all entries in the current working directory")]
    input: Vec<PathBuf>,
}

#[derive(Subcommand, Debug, Clone)]
enum Command {
    #[command(alias="i", about="Launch the terminal user interface")]
    Interactive {
        #[arg(short='e', long="no-entry-check", help="Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems")]
        no_entry_check: bool,

        #[arg(value_name = "INPUT", help="One or more input files or directories. If unset, we will use all entries in the current working directory")]
        input: Vec<PathBuf>,
    },
    #[command(alias="a", about="Aggregate the consumed space of one or more directories or files")]
    Aggregate {
        #[arg(long="stats", help="If set, print additional statistics about the file traversal to stderr")]
        stats: bool,

        #[arg(long="no-sort", help="If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending")]
        no_sort: bool,

        #[arg(long="no-total", help="If set, no total column will be computed for multiple inputs")]
        no_total: bool,

        #[arg(value_name = "INPUT", help="One or more input files or directories. If unset, we will use all entries in the current working directory")]
        input: Vec<PathBuf>,
    },
    #[command(about="Generate shell completions")]
    Completions {
        #[arg(value_enum)]
        shell: clap_complete::Shell,
    }
}

fn main() {
    let args = Args::parse();
    let mut log_writer: Option<std::fs::File> = None;
    if let Some(ref log_path) = args.log_file {
        match std::fs::File::create(log_path) {
            Ok(f) => log_writer = Some(f),
            Err(_) => {}
        }
    }
    if let Some(ref mut lw) = log_writer {
        use std::io::Write;
        let now = chrono::Local::now();
        let time_str = now.format("%H:%M:%S").to_string();
        let mut log_content = String::new();
        log_content.push_str(&format!("{} [INFO] dua options=Args {{\n", time_str));
        match &args.command {
            Some(Command::Aggregate { stats, no_sort, no_total, input }) => {
                log_content.push_str("    command: Some(\n");
                log_content.push_str("        Aggregate {\n");
                log_content.push_str(&format!("            statistics: {},\n", stats));
                log_content.push_str(&format!("            no_sort: {},\n", no_sort));
                log_content.push_str(&format!("            no_total: {},\n", no_total));
                log_content.push_str("            input: [\n");
                for p in input {
                    log_content.push_str(&format!("                \"{}\",\n", p.display()));
                }
                log_content.push_str("            ],\n");
                log_content.push_str("        },\n");
                log_content.push_str("    ),\n");
            },
            Some(Command::Interactive { no_entry_check: _, input }) => {
                log_content.push_str("    command: Some(\n");
                log_content.push_str("        Interactive {\n");
                log_content.push_str("            no_entry_check: false,\n");
                log_content.push_str("            input: [\n");
                for p in input {
                    log_content.push_str(&format!("                \"{}\",\n", p.display()));
                }
                log_content.push_str("            ],\n");
                log_content.push_str("        },\n");
                log_content.push_str("    ),\n");
            },
            Some(Command::Completions { shell: _ }) => {
                log_content.push_str("    command: Some(\n");
                log_content.push_str("        Completions {\n");
                log_content.push_str("            shell: Bash,\n");
                log_content.push_str("        },\n");
                log_content.push_str("    ),\n");
            },
            None => {
                log_content.push_str("    command: None,\n");
            }
        }
        log_content.push_str(&format!("    threads: {},\n", args.threads));
        let fmt_str = match args.format {
            Format::Metric => "Metric",
            Format::Binary => "Binary",
            Format::Bytes => "Bytes",
            Format::Gb => "Gb",
            Format::Gib => "Gib",
            Format::Mb => "Mb",
            Format::Mib => "Mib",
        };
        log_content.push_str(&format!("    format: {},\n", fmt_str));
        log_content.push_str(&format!("    apparent_size: {},\n", args.apparent_size));
        log_content.push_str(&format!("    count_hard_links: {},\n", args.count_hard_links));
        log_content.push_str(&format!("    stay_on_filesystem: {},\n", args.stay_on_filesystem));
        log_content.push_str("    ignore_dirs: [\n");
        for d in &args.ignore_dirs {
            log_content.push_str(&format!("        \"{}\",\n", d));
        }
        log_content.push_str("    ],\n");
        log_content.push_str("    input: [\n");
        for p in &args.input {
            log_content.push_str(&format!("        \"{}\",\n", p.display()));
        }
        log_content.push_str("    ],\n");
        match &args.log_file {
            Some(p) => {
                log_content.push_str("    log_file: Some(\n");
                log_content.push_str(&format!("        \"{}\",\n", p.display()));
                log_content.push_str("    ),\n");
            },
            None => {
                log_content.push_str("    log_file: None,\n");
            }
        }
        log_content.push_str("}\n");
        let _ = lw.write_all(log_content.as_bytes());
        let mut canon_set = std::collections::BTreeSet::new();
        for d in &args.ignore_dirs {
            let canon = match std::fs::canonicalize(d) {
                Ok(p) => p.display().to_string(),
                Err(_) => d.clone(),
            };
            canon_set.insert(canon);
        }
        let canon_list: Vec<String> = canon_set.into_iter().collect();
        let list_str = canon_list.iter().map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", ");
        let log2 = format!("{} [INFO] Ignoring canonicalized {{{}}}\n", time_str, list_str);
        let _ = lw.write_all(log2.as_bytes());
    }

    match args.command {
        Some(Command::Completions { shell }) => {
            let mut cmd = Args::command();
            let bin_name = "dua";
            clap_complete::generate(shell, &mut cmd, bin_name, &mut std::io::stdout());
            return;
        },
        Some(Command::Interactive { .. }) => {
            eprintln!("Error: Interactive mode requires a connected terminal");
            std::process::exit(1);
        },
        Some(Command::Aggregate { stats, no_sort, no_total, input }) => {
            let inputs = if input.is_empty() && args.input.is_empty() {
                match std::fs::read_dir(".") {
                    Ok(rd) => {
                        let mut v = Vec::new();
                        for e in rd {
                            if let Ok(e) = e {
                                v.push(e.path());
                            }
                        }
                        v
                    },
                    Err(_) => Vec::new(),
                }
            } else if !input.is_empty() {
                input
            } else {
                args.input.clone()
            };
            let result = run_aggregate(inputs, &args, stats, no_sort, no_total, log_writer);
            std::process::exit(result);
        },
        None => {
            let inputs = if args.input.is_empty() {
                match std::fs::read_dir(".") {
                    Ok(rd) => {
                        let mut v = Vec::new();
                        for e in rd {
                            if let Ok(e) = e {
                                v.push(e.path());
                            }
                        }
                        v
                    },
                    Err(_) => Vec::new(),
                }
            } else {
                args.input.clone()
            };
            let result = run_aggregate(inputs, &args, false, false, false, log_writer);
            std::process::exit(result);
        }
    }
}

#[derive(Clone, Debug)]
struct Entry {
    path: PathBuf,
    size: u64,
    display_size: u64,
    is_dir: bool,
    is_error: bool,
}

fn run_aggregate(input_paths: Vec<PathBuf>, global_args: &Args, stats: bool, no_sort: bool, no_total: bool, mut log_writer: Option<std::fs::File>) -> i32 {
    let apparent = global_args.apparent_size;
    let count_hard_links = global_args.count_hard_links;
    let stay_on_fs = global_args.stay_on_filesystem;
    let ignore_dirs_raw = global_args.ignore_dirs.clone();

    let mut ignore_canonical: HashSet<PathBuf> = HashSet::new();
    for d in &ignore_dirs_raw {
        if let Ok(c) = fs::canonicalize(d) {
            ignore_canonical.insert(c);
        } else {
            ignore_canonical.insert(PathBuf::from(d));
        }
    }

    let mut input_canonical_set: HashSet<PathBuf> = HashSet::new();
    for p in &input_paths {
        if let Ok(c) = fs::canonicalize(p) {
            input_canonical_set.insert(c);
        } else {
            if let Ok(abs) = std::fs::canonicalize(".") {
                let abs_path = if p.is_absolute() { p.clone() } else { abs.join(p) };
                if let Ok(c) = fs::canonicalize(&abs_path) {
                    input_canonical_set.insert(c);
                } else {
                    input_canonical_set.insert(abs_path);
                }
            } else {
                input_canonical_set.insert(p.clone());
            }
        }
    }

    let mut seen_inodes: HashSet<(u64, u64)> = HashSet::new();
    let mut entries_traversed: u64 = 0;
    let mut smallest: u64 = u64::MAX;
    let mut largest: u64 = 0;

    let mut results: Vec<Entry> = Vec::new();
    let mut total_size: u64 = 0;
    let mut total_errors: usize = 0;

    let is_single_dir_listing = if input_paths.len() == 1 {
        let p = &input_paths[0];
        match fs::metadata(p) {
            Ok(m) => m.is_dir(),
            Err(_) => false,
        }
    } else {
        false
    };

    if is_single_dir_listing {
        let dir_path = &input_paths[0];
        let root_dev = fs::metadata(dir_path).map(|m| m.dev()).unwrap_or(0);
        let read_dir = match fs::read_dir(dir_path) {
            Ok(rd) => rd,
            Err(_) => {
                if stats {
                    eprintln!("Statistics {{ entries_traversed: 0, smallest_file_in_bytes: 0, largest_file_in_bytes: 0 }}");
                }
                return 0;
            }
        };
        let mut children: Vec<PathBuf> = Vec::new();
        for entry in read_dir {
            if let Ok(e) = entry {
                children.push(e.path());
            }
        }
        let mut child_entries: Vec<Entry> = Vec::new();
        let mut child_total: u64 = 0;
        for child_path in children {
            let lstat = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if lstat.file_type().is_symlink() {
                continue;
            }
            let is_dir = lstat.is_dir();
            let (size, trav, small, large, _has_error) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, false);
            entries_traversed += trav;
            if small < smallest { smallest = small; }
            if large > largest { largest = large; }
            let display_path = child_path.file_name().map(|n| PathBuf::from(n)).unwrap_or(child_path.clone());
            child_entries.push(Entry {
                path: display_path,
                size,
                display_size: size,
                is_dir,
                is_error: false,
            });
            child_total += size;
        }

        if !no_sort {
            child_entries.sort_by(|a,b| {
                if a.size != b.size {
                    a.size.cmp(&b.size)
                } else {
                    a.path.cmp(&b.path)
                }
            });
        } else {
            child_entries.sort_by(|a,b| a.path.cmp(&b.path));
        }

        for entry in &child_entries {
            let formatted = global_args.format.display(entry.display_size);
            let size_colored = format!("\x1b[32m{}\x1b[39m", formatted);
            let path_str = entry.path.display().to_string();
            if entry.is_dir {
                println!("{} \x1b[36m{}\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }
        if child_entries.len() > 1 && !no_total {
            let total_formatted = global_args.format.display(child_total);
            let size_colored = format!("\x1b[32m{}\x1b[39m", total_formatted);
            println!("{} total", size_colored);
        }

        if stats {
            if entries_traversed == 0 {
                smallest = 0;
                largest = 0;
            } else if smallest == u64::MAX {
                smallest = 0;
            }
            eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, smallest, largest);
        }
        return 0;
    } else {
        for input_path in &input_paths {
            let lstat = match fs::symlink_metadata(input_path) {
                Ok(m) => m,
                Err(_) => {
                    results.push(Entry {
                        path: input_path.clone(),
                        size: 0,
                        display_size: 0,
                        is_dir: true,
                        is_error: true,
                    });
                    total_errors += 1;
                    continue;
                }
            };
            let is_symlink = lstat.file_type().is_symlink();
            if is_symlink {
                if fs::metadata(input_path).is_err() {
                    results.push(Entry {
                        path: input_path.clone(),
                        size: 0,
                        display_size: 0,
                        is_dir: true,
                        is_error: true,
                    });
                    total_errors += 1;
                    continue;
                }
                let meta = fs::metadata(input_path).unwrap();
                if meta.is_dir() {
                    let root_dev = meta.dev();
                    let (size, trav, small, large, _err) = compute_size_recursive(input_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, true);
                    entries_traversed += trav;
                    if small < smallest { smallest = small; }
                    if large > largest { largest = large; }
                    results.push(Entry {
                        path: input_path.clone(),
                        size,
                        display_size: size,
                        is_dir: true,
                        is_error: false,
                    });
                    total_size += size;
                } else {
                    let size = if apparent { lstat.size() } else { lstat.blocks()*512 };
                    entries_traversed += 1;
                    if size < smallest { smallest = size; }
                    if size > largest { largest = size; }
                    results.push(Entry {
                        path: input_path.clone(),
                        size,
                        display_size: size,
                        is_dir: false,
                        is_error: false,
                    });
                    total_size += size;
                }
            } else {
                if lstat.is_dir() {
                    let root_dev = lstat.dev();
                    let (size, trav, small, large, _err) = compute_size_recursive(input_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, true);
                    entries_traversed += trav;
                    if small < smallest { smallest = small; }
                    if large > largest { largest = large; }
                    results.push(Entry {
                        path: input_path.clone(),
                        size,
                        display_size: size,
                        is_dir: true,
                        is_error: false,
                    });
                    total_size += size;
                } else {
                    let dev = lstat.dev();
                    let ino = lstat.ino();
                    let nlink = lstat.nlink();
                    let mut size = if apparent { lstat.size() } else { lstat.blocks()*512 };
                    if !count_hard_links && nlink > 1 {
                        if seen_inodes.contains(&(dev, ino)) {
                            size = 0;
                        } else {
                            seen_inodes.insert((dev, ino));
                        }
                    }
                    entries_traversed += 1;
                    if size < smallest { smallest = size; }
                    if size > largest { largest = size; }
                    results.push(Entry {
                        path: input_path.clone(),
                        size,
                        display_size: size,
                        is_dir: false,
                        is_error: false,
                    });
                    total_size += size;
                }
            }
        }

        let mut display_results: Vec<Entry> = Vec::new();
        if !no_sort {
            let mut sorted = results.clone();
            sorted.sort_by(|a,b| a.size.cmp(&b.size));
            display_results = sorted;
        } else {
            display_results = results.iter().filter(|e| !e.is_error).cloned().collect();
        }

        for entry in &display_results {
            let formatted = global_args.format.display(entry.display_size);
            let size_colored = format!("\x1b[32m{}\x1b[39m", formatted);
            let path_str = entry.path.display().to_string();
            if entry.is_error {
                println!("{} \x1b[36m{}\x1b[39m  <1 IO Error>", size_colored, path_str);
            } else if entry.is_dir {
                println!("{} \x1b[36m{}\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }

        let mut print_total = false;
        if !no_total && input_paths.len() > 1 {
            print_total = true;
        }

        if print_total {
            let total_formatted = global_args.format.display(total_size);
            let size_colored = format!("\x1b[32m{}\x1b[39m", total_formatted);
            if total_errors == 0 {
                println!("{} total", size_colored);
            } else if total_errors == 1 {
                println!("{} total  <1 IO Error>", size_colored);
            } else {
                println!("{} total  <{} IO Errors>", size_colored, total_errors);
            }
        }

        if stats {
            if entries_traversed == 0 {
                smallest = 0;
                largest = 0;
            } else if smallest == u64::MAX {
                smallest = 0;
            }
            eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, smallest, largest);
        }

        if total_errors > 0 { 1 } else { 0 }
    }
}

fn compute_size_recursive(
    path: &Path,
    apparent: bool,
    count_hard_links: bool,
    stay_on_fs: bool,
    ignore_canonical: &HashSet<PathBuf>,
    input_canonical_set: &HashSet<PathBuf>,
    seen_inodes: &mut HashSet<(u64, u64)>,
    root_dev: u64,
    log_writer: &mut Option<std::fs::File>,
    is_root_dir: bool,
) -> (u64, u64, u64, u64, bool) {
    let lstat = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return (0, 0, u64::MAX, 0, true),
    };
    if lstat.file_type().is_symlink() {
        if let Ok(meta) = fs::metadata(path) {
            if meta.is_dir() {
                let target_path = fs::canonicalize(path).unwrap_or(path.to_path_buf());
                if ignore_canonical.contains(&target_path) && !input_canonical_set.contains(&target_path) {
                    let own_size = if apparent { meta.size() } else { meta.blocks()*512 };
                    return (own_size, 1, own_size, own_size, false);
                }
                let mut total_size = if apparent { meta.size() } else { meta.blocks()*512 };
                let mut entries = 1;
                let mut smallest = total_size;
                let mut largest = total_size;
                let rd = match fs::read_dir(path) {
                    Ok(rd) => rd,
                    Err(_) => return (total_size, entries, smallest, largest, true),
                };
                for entry in rd {
                    if let Ok(e) = entry {
                        let child_path = e.path();
                        let child_lstat = match fs::symlink_metadata(&child_path) {
                            Ok(m) => m,
                            Err(_) => continue,
                        };
                        if child_lstat.file_type().is_symlink() {
                            continue;
                        }
