                let v = bytes as f64 / 1_000_000.0;
                format!("{:9.2} MB", v)
            },
            Format::Mib => {
                let v = bytes as f64 / (1024.0*1024.0);
                format!("{:8.2} MiB", v)
            },
        }
    }
}

const MAIN_LONG: &str = include_str!("../main_long.txt");
const MAIN_SHORT: &str = include_str!("../main_short.txt");
const AGG_LONG: &str = include_str!("../agg_long.txt");
const INTER_LONG: &str = include_str!("../inter_long.txt");
const COMP_LONG: &str = include_str!("../comp_long.txt");
const HELP_HELP: &str = include_str!("../help_help.txt");
const BASH_COMP: &str = include_str!("../bash_completion.txt");
const ZSH_COMP: &str = include_str!("../zsh_completion.txt");
const FISH_COMP: &str = include_str!("../fish_completion.txt");
const ELVISH_COMP: &str = include_str!("../elvish_completion.txt");
const POWERSHELL_COMP: &str = include_str!("../powershell_completion.txt");

fn build_cli() -> Command {
    Command::new("dua")
        .version("2.32.2")
        .about("A tool to learn about disk usage, fast!")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("threads")
                .short('t')
                .long("threads")
                .value_name("THREADS")
                .default_value("0")
                .help("The amount of threads to use. Defaults to 0, indicating the amount of logical processors. Set to 1 to use only a single thread")
        )
        .arg(
            Arg::new("format")
                .short('f')
                .long("format")
                .value_name("FORMAT")
                .default_value("binary")
                .value_parser(PossibleValuesParser::new(["metric","binary","bytes","gb","gib","mb","mib"]))
                .help("The format with which to print byte counts")
        )
        .arg(
            Arg::new("apparent-size")
                .short('A')
                .long("apparent-size")
                .action(ArgAction::SetTrue)
                .help("Display apparent size instead of disk usage")
        )
        .arg(
            Arg::new("count-hard-links")
                .short('l')
                .long("count-hard-links")
                .action(ArgAction::SetTrue)
                .help("Count hard-linked files each time they are seen")
        )
        .arg(
            Arg::new("stay-on-filesystem")
                .short('x')
                .long("stay-on-filesystem")
                .action(ArgAction::SetTrue)
                .help("If set, we will not cross filesystems or traverse mount points")
        )
        .arg(
            Arg::new("ignore-dirs")
                .short('i')
                .long("ignore-dirs")
                .value_name("IGNORE_DIRS")
                .action(ArgAction::Append)
                .default_values(["/proc","/dev","/sys","/run"])
                .help("One or more absolute directories to ignore. Note that these are not ignored if they are passed as input path.\n\nHence, they will only be ignored if they are eventually reached as part of the traversal.")
        )
        .arg(
            Arg::new("log-file")
                .long("log-file")
                .value_name("LOG_FILE")
                .help("Write a log file with debug information, including panics")
        )
        .arg(
            Arg::new("help")
                .short('h')
                .long("help")
                .action(ArgAction::SetTrue)
                .help("Print help")
        )
        .arg(
            Arg::new("version")
                .short('V')
                .long("version")
                .action(ArgAction::SetTrue)
                .help("Print version")
        )
        .arg(
            Arg::new("INPUT")
                .value_name("INPUT")
                .num_args(0..)
                .help("One or more input files or directories. If unset, we will use all entries in the current working directory")
        )
        .subcommand(
            Command::new("interactive")
                .visible_alias("i")
                .about("Launch the terminal user interface")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(
                    Arg::new("no-entry-check")
                        .short('e')
                        .long("no-entry-check")
                        .action(ArgAction::SetTrue)
                        .help("Do not check entries for presence when listing a directory to avoid slugging performance on slow filesystems")
                )
                .arg(
                    Arg::new("help")
                        .short('h')
                        .long("help")
                        .action(ArgAction::SetTrue)
                        .help("Print help")
                )
                .arg(
                    Arg::new("INPUT")
                        .value_name("INPUT")
                        .num_args(0..)
                        .help("One or more input files or directories. If unset, we will use all entries in the current working directory")
                )
        )
        .subcommand(
            Command::new("aggregate")
                .visible_alias("a")
                .about("Aggregate the consumed space of one or more directories or files")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(
                    Arg::new("stats")
                        .long("stats")
                        .action(ArgAction::SetTrue)
                        .help("If set, print additional statistics about the file traversal to stderr")
                )
                .arg(
                    Arg::new("no-sort")
                        .long("no-sort")
                        .action(ArgAction::SetTrue)
                        .help("If set, paths will be printed in their order of occurrence on the command-line. Otherwise they are sorted by their size in bytes, ascending")
                )
                .arg(
                    Arg::new("no-total")
                        .long("no-total")
                        .action(ArgAction::SetTrue)
                        .help("If set, no total column will be computed for multiple inputs")
                )
                .arg(
                    Arg::new("help")
                        .short('h')
                        .long("help")
                        .action(ArgAction::SetTrue)
                        .help("Print help")
                )
                .arg(
                    Arg::new("INPUT")
                        .value_name("INPUT")
                        .num_args(0..)
                        .help("One or more input files or directories. If unset, we will use all entries in the current working directory")
                )
        )
        .subcommand(
            Command::new("completions")
                .about("Generate shell completions")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(
                    Arg::new("SHELL")
                        .value_parser(PossibleValuesParser::new(["bash","elvish","fish","powershell","zsh"]))
                        .required(true)
                )
                .arg(
                    Arg::new("help")
                        .short('h')
                        .long("help")
                        .action(ArgAction::SetTrue)
                        .help("Print help")
                )
        )
        .subcommand(
            Command::new("help")
                .about("Print this message or the help of the given subcommand(s)")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .arg(
                    Arg::new("COMMAND")
                        .num_args(0..)
                )
        )
}

#[derive(Clone, Debug)]
struct GlobalArgs {
    format: Format,
    apparent_size: bool,
    count_hard_links: bool,
    stay_on_filesystem: bool,
    ignore_dirs: Vec<String>,
    threads: usize,
}

fn main() {
    let raw_args: Vec<String> = std::env::args().collect();
    if raw_args.len() >= 2 && raw_args[1] == "help" {
        if raw_args.len() == 2 {
            print!("{}", MAIN_LONG);
            return;
        } else if raw_args.len() == 3 {
            match raw_args[2].as_str() {
                "aggregate" | "a" => { print!("{}", AGG_LONG); return; },
                "interactive" | "i" => { print!("{}", INTER_LONG); return; },
                "completions" => { print!("{}", COMP_LONG); return; },
                "help" => { print!("{}", HELP_HELP); return; },
                _ => {
                    eprintln!("error: unrecognized subcommand '{}'\n\nUsage: executable help [COMMAND]...\n\nFor more information, try '--help'.", raw_args[2]);
                    std::process::exit(2);
                }
            }
        } else {
            let sub = raw_args[2].as_str();
            if sub == "aggregate" || sub == "a" || sub == "interactive" || sub == "i" || sub == "completions" {
                if raw_args.len() > 3 {
                    eprintln!("error: unrecognized subcommand '{}'\n\nUsage: executable help [COMMAND]...\n\nFor more information, try '--help'.", raw_args[3]);
                    std::process::exit(2);
                } else {
                    match sub {
                        "aggregate" | "a" => { print!("{}", AGG_LONG); return; },
                        "interactive" | "i" => { print!("{}", INTER_LONG); return; },
                        "completions" => { print!("{}", COMP_LONG); return; },
                        _ => { print!("{}", MAIN_LONG); return; }
                    }
                }
            } else {
                eprintln!("error: unrecognized subcommand '{}'\n\nUsage: executable help [COMMAND]...\n\nFor more information, try '--help'.", sub);
                std::process::exit(2);
            }
        }
    }

    let mut cmd = build_cli();
    let matches_result = cmd.clone().try_get_matches();

    match matches_result {
        Ok(matches) => {
            if matches.get_flag("help") {
                let is_long = raw_args.iter().any(|a| a == "--help");
                if is_long {
                    print!("{}", MAIN_LONG);
                } else {
                    print!("{}", MAIN_SHORT);
                }
                return;
            }
            if matches.get_flag("version") {
                println!("dua 2.32.2");
                return;
            }

            if let Some((sub_name, sub_matches)) = matches.subcommand() {
                match sub_name {
                    "completions" => {
                        if sub_matches.get_flag("help") {
                            print!("{}", COMP_LONG);
                            return;
                        }
                        let shell_str = sub_matches.get_one::<String>("SHELL").unwrap();
                        match shell_str.as_str() {
                            "bash" => print!("{}", BASH_COMP),
                            "zsh" => print!("{}", ZSH_COMP),
                            "fish" => print!("{}", FISH_COMP),
                            "elvish" => print!("{}", ELVISH_COMP),
                            "powershell" => print!("{}", POWERSHELL_COMP),
                            _ => print!("{}", BASH_COMP),
                        }
                        return;
                    },
                    "interactive" => {
                        if sub_matches.get_flag("help") {
                            print!("{}", INTER_LONG);
                            return;
                        }
                        eprintln!("Error: Interactive mode requires a connected terminal");
                        std::process::exit(1);
                    },
                    "aggregate" => {
                        if sub_matches.get_flag("help") {
                            print!("{}", AGG_LONG);
                            return;
                        }
                        let threads_str = matches.get_one::<String>("threads").unwrap().clone();
                        let threads: usize = threads_str.parse().unwrap_or(0);
                        let format_str = matches.get_one::<String>("format").unwrap().clone();
                        let format = Format::from_str(&format_str).unwrap();
                        let apparent_size = matches.get_flag("apparent-size");
                        let count_hard_links = matches.get_flag("count-hard-links");
                        let stay_on_filesystem = matches.get_flag("stay-on-filesystem");
                        let ignore_dirs: Vec<String> = matches.get_many::<String>("ignore-dirs").unwrap_or_default().cloned().collect();
                        let log_file: Option<PathBuf> = matches.get_one::<String>("log-file").map(|s| PathBuf::from(s));
                        let top_input: Vec<PathBuf> = matches.get_many::<String>("INPUT").unwrap_or_default().map(|s| PathBuf::from(s)).collect();

                        let stats = sub_matches.get_flag("stats");
                        let no_sort = sub_matches.get_flag("no-sort");
                        let no_total = sub_matches.get_flag("no-total");
                        let sub_input: Vec<PathBuf> = sub_matches.get_many::<String>("INPUT").unwrap_or_default().map(|s| PathBuf::from(s)).collect();

                        let inputs = if sub_input.is_empty() && top_input.is_empty() {
                            match std::fs::read_dir(".") {
                                Ok(rd) => rd.filter_map(|e| e.ok().map(|e| e.path())).collect(),
                                Err(_) => Vec::new(),
                            }
                        } else if !sub_input.is_empty() {
                            sub_input
                        } else {
                            top_input.clone()
                        };

                        let global = GlobalArgs {
                            format: format.clone(),
                            apparent_size,
                            count_hard_links,
                            stay_on_filesystem,
                            ignore_dirs: ignore_dirs.clone(),
                            threads,
                        };

                        let mut log_writer: Option<std::fs::File> = None;
                        if let Some(ref log_path) = log_file {
                            if let Ok(f) = std::fs::File::create(log_path) {
                                log_writer = Some(f);
                            }
                            if let Some(ref mut lw) = log_writer {
                                use std::io::Write;
                                let now = chrono::Local::now();
                                let time_str = now.format("%H:%M:%S").to_string();
                                let mut log_content = String::new();
                                log_content.push_str(&format!("{} [INFO] dua options=Args {{\n", time_str));
                                log_content.push_str("    command: Some(\n");
                                log_content.push_str("        Aggregate {\n");
                                log_content.push_str(&format!("            statistics: {},\n", stats));
                                log_content.push_str(&format!("            no_sort: {},\n", no_sort));
                                log_content.push_str(&format!("            no_total: {},\n", no_total));
                                log_content.push_str("            input: [\n");
                                for p in &inputs {
                                    log_content.push_str(&format!("                \"{}\",\n", p.display()));
                                }
                                log_content.push_str("            ],\n");
                                log_content.push_str("        },\n");
                                log_content.push_str("    ),\n");
                                log_content.push_str(&format!("    threads: {},\n", threads));
                                let fmt_str = match &format {
                                    Format::Metric => "Metric",
                                    Format::Binary => "Binary",
                                    Format::Bytes => "Bytes",
                                    Format::Gb => "Gb",
                                    Format::Gib => "Gib",
                                    Format::Mb => "Mb",
                                    Format::Mib => "Mib",
                                };
                                log_content.push_str(&format!("    format: {},\n", fmt_str));
                                log_content.push_str(&format!("    apparent_size: {},\n", apparent_size));
                                log_content.push_str(&format!("    count_hard_links: {},\n", count_hard_links));
                                log_content.push_str(&format!("    stay_on_filesystem: {},\n", stay_on_filesystem));
                                log_content.push_str("    ignore_dirs: [\n");
                                for d in &global.ignore_dirs {
                                    log_content.push_str(&format!("        \"{}\",\n", d));
                                }
                                log_content.push_str("    ],\n");
                                log_content.push_str("    input: [\n");
                                for p in &top_input {
                                    log_content.push_str(&format!("        \"{}\",\n", p.display()));
                                }
                                log_content.push_str("    ],\n");
                                match &log_file {
                                    Some(p) => {
                                        log_content.push_str("    log_file: Some(\n");
                                        log_content.push_str(&format!("        \"{}\",\n", p.display()));
                                        log_content.push_str("    ),\n");
                                    },
                                    None => {
                                        log_content.push_str("    log_file: None,\n");
                                    }
                                }
                                log_content.push_str("}\n");
                                let _ = lw.write_all(log_content.as_bytes());
                                let mut canon_set = BTreeSet::new();
                                for d in &global.ignore_dirs {
                                    let canon = match std::fs::canonicalize(d) {
                                        Ok(p) => p.display().to_string(),
                                        Err(_) => d.clone(),
                                    };
                                    canon_set.insert(canon);
                                }
                                let canon_list: Vec<String> = canon_set.into_iter().collect();
                                let list_str = canon_list.iter().map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", ");
                                let log2 = format!("{} [INFO] Ignoring canonicalized {{{}}}\n", time_str, list_str);
                                let _ = lw.write_all(log2.as_bytes());
                            }
                        }

                        let result = run_aggregate(inputs, &global, stats, no_sort, no_total, log_writer);
                        std::process::exit(result);
                    },
                    "help" => {
                        print!("{}", MAIN_LONG);
                        return;
                    },
                    _ => {}
                }
            } else {
                let threads_str = matches.get_one::<String>("threads").unwrap().clone();
                let threads: usize = threads_str.parse().unwrap_or(0);
                let format_str = matches.get_one::<String>("format").unwrap().clone();
                let format = Format::from_str(&format_str).unwrap();
                let apparent_size = matches.get_flag("apparent-size");
                let count_hard_links = matches.get_flag("count-hard-links");
                let stay_on_filesystem = matches.get_flag("stay-on-filesystem");
                let ignore_dirs: Vec<String> = matches.get_many::<String>("ignore-dirs").unwrap_or_default().cloned().collect();
                let log_file: Option<PathBuf> = matches.get_one::<String>("log-file").map(|s| PathBuf::from(s));
                let top_input: Vec<PathBuf> = matches.get_many::<String>("INPUT").unwrap_or_default().map(|s| PathBuf::from(s)).collect();

                let inputs = if top_input.is_empty() {
                    match std::fs::read_dir(".") {
                        Ok(rd) => rd.filter_map(|e| e.ok().map(|e| e.path())).collect(),
                        Err(_) => Vec::new(),
                    }
                } else {
                    top_input.clone()
                };

                let global = GlobalArgs {
                    format: format.clone(),
                    apparent_size,
                    count_hard_links,
                    stay_on_filesystem,
                    ignore_dirs: ignore_dirs.clone(),
                    threads,
                };

                let mut log_writer: Option<std::fs::File> = None;
                if let Some(ref log_path) = log_file {
                    if let Ok(f) = std::fs::File::create(log_path) {
                        log_writer = Some(f);
                    }
                    if let Some(ref mut lw) = log_writer {
                        use std::io::Write;
                        let now = chrono::Local::now();
                        let time_str = now.format("%H:%M:%S").to_string();
                        let mut log_content = String::new();
                        log_content.push_str(&format!("{} [INFO] dua options=Args {{\n", time_str));
                        log_content.push_str("    command: None,\n");
                        log_content.push_str(&format!("    threads: {},\n", threads));
                        let fmt_str = match &format {
                            Format::Metric => "Metric",
                            Format::Binary => "Binary",
                            Format::Bytes => "Bytes",
                            Format::Gb => "Gb",
                            Format::Gib => "Gib",
                            Format::Mb => "Mb",
                            Format::Mib => "Mib",
                        };
                        log_content.push_str(&format!("    format: {},\n", fmt_str));
                        log_content.push_str(&format!("    apparent_size: {},\n", apparent_size));
                        log_content.push_str(&format!("    count_hard_links: {},\n", count_hard_links));
                        log_content.push_str(&format!("    stay_on_filesystem: {},\n", stay_on_filesystem));
                        log_content.push_str("    ignore_dirs: [\n");
                        for d in &global.ignore_dirs {
                            log_content.push_str(&format!("        \"{}\",\n", d));
                        }
                        log_content.push_str("    ],\n");
                        log_content.push_str("    input: [\n");
                        for p in &top_input {
                            log_content.push_str(&format!("        \"{}\",\n", p.display()));
                        }
                        log_content.push_str("    ],\n");
                        match &log_file {
                            Some(p) => {
                                log_content.push_str("    log_file: Some(\n");
                                log_content.push_str(&format!("        \"{}\",\n", p.display()));
                                log_content.push_str("    ),\n");
                            },
                            None => {
                                log_content.push_str("    log_file: None,\n");
                            }
                        }
                        log_content.push_str("}\n");
                        let _ = lw.write_all(log_content.as_bytes());
                        let mut canon_set = BTreeSet::new();
                        for d in &global.ignore_dirs {
                            let canon = match std::fs::canonicalize(d) {
                                Ok(p) => p.display().to_string(),
                                Err(_) => d.clone(),
                            };
                            canon_set.insert(canon);
                        }
                        let canon_list: Vec<String> = canon_set.into_iter().collect();
                        let list_str = canon_list.iter().map(|s| format!("\"{}\"", s)).collect::<Vec<_>>().join(", ");
                        let log2 = format!("{} [INFO] Ignoring canonicalized {{{}}}\n", time_str, list_str);
                        let _ = lw.write_all(log2.as_bytes());
                    }
                }

                let result = run_aggregate(inputs, &global, false, false, false, log_writer);
                std::process::exit(result);
            }
        },
        Err(e) => {
            e.print().unwrap();
            std::process::exit(2);
        }
    }
}

#[derive(Clone, Debug)]
struct Entry {
    path: PathBuf,
    size: u64,
    display_size: u64,
    is_dir: bool,
    is_error: bool,
}

fn run_aggregate(input_paths: Vec<PathBuf>, global_args: &GlobalArgs, stats: bool, no_sort: bool, no_total: bool, mut log_writer: Option<std::fs::File>) -> i32 {
    let apparent = global_args.apparent_size;
    let count_hard_links = global_args.count_hard_links;
    let stay_on_fs = global_args.stay_on_filesystem;
    let ignore_dirs_raw = global_args.ignore_dirs.clone();

    let mut ignore_canonical: HashSet<PathBuf> = HashSet::new();
    for d in &ignore_dirs_raw {
        if let Ok(c) = fs::canonicalize(d) {
            ignore_canonical.insert(c);
        } else {
            ignore_canonical.insert(PathBuf::from(d));
        }
    }

    let mut input_canonical_set: HashSet<PathBuf> = HashSet::new();
    for p in &input_paths {
        if let Ok(c) = fs::canonicalize(p) {
            input_canonical_set.insert(c);
        } else {
            if let Ok(abs) = std::fs::canonicalize(".") {
                let abs_path = if p.is_absolute() { p.clone() } else { abs.join(p) };
                if let Ok(c) = fs::canonicalize(&abs_path) {
                    input_canonical_set.insert(c);
                } else {
                    input_canonical_set.insert(abs_path);
                }
            } else {
                input_canonical_set.insert(p.clone());
            }
        }
    }

    let mut seen_inodes: HashSet<(u64, u64)> = HashSet::new();
    let mut entries_traversed: u64 = 0;
    let mut smallest: u64 = u64::MAX;
    let mut largest: u64 = 0;

    let mut results: Vec<Entry> = Vec::new();
    let mut total_size: u64 = 0;
    let mut total_errors: usize = 0;

    let is_single_dir_listing = if input_paths.len() == 1 {
        let p = &input_paths[0];
        match fs::metadata(p) {
            Ok(m) => m.is_dir(),
            Err(_) => false,
        }
    } else {
        false
    };

    if is_single_dir_listing {
        let dir_path = &input_paths[0];
        let root_dev = fs::metadata(dir_path).map(|m| m.dev()).unwrap_or(0);
        let read_dir = match fs::read_dir(dir_path) {
            Ok(rd) => rd,
            Err(_) => {
                if stats {
                    eprintln!("Statistics {{ entries_traversed: 0, smallest_file_in_bytes: 0, largest_file_in_bytes: 0 }}");
                }
                return 0;
            }
        };
        let mut children: Vec<PathBuf> = Vec::new();
        for entry in read_dir {
            if let Ok(e) = entry {
                children.push(e.path());
            }
        }
        let mut child_entries: Vec<Entry> = Vec::new();
        let mut child_total: u64 = 0;
        for child_path in children {
            let lstat = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if lstat.file_type().is_symlink() {
                continue;
            }
            let is_dir = lstat.is_dir();
            let (size, trav, small, large, _has_error) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, false);
            entries_traversed += trav;
            if small < smallest { smallest = small; }
            if large > largest { largest = large; }
            let display_path = child_path.file_name().map(|n| PathBuf::from(n)).unwrap_or(child_path.clone());
            child_entries.push(Entry {
                path: display_path,
                size,
                display_size: size,
                is_dir,
                is_error: false,
            });
            child_total += size;
        }

        if !no_sort {
            child_entries.sort_by(|a,b| {
                if a.size != b.size {
                    a.size.cmp(&b.size)
                } else {
                    a.path.cmp(&b.path)
                }
            });
        } else {
            child_entries.sort_by(|a,b| a.path.cmp(&b.path));
        }

        for entry in &child_entries {
            let formatted = global_args.format.display(entry.display_size);
            let size_colored = format!("\x1b[32m{}\x1b[39m", formatted);
            let path_str = entry.path.display().to_string();
            if entry.is_dir {
                println!("{} \x1b[36m{}\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }
        if child_entries.len() > 1 && !no_total {
            let total_formatted = global_args.format.display(child_total);
            let size_colored = format!("\x1b[32m{}\x1b[39m", total_formatted);
            println!("{} total", size_colored);
        }

        if stats {
            if entries_traversed == 0 {
                smallest = 0;
                largest = 0;
            } else if smallest == u64::MAX {
                smallest = 0;
            }
            eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, smallest, largest);
        }
        return 0;
    } else {
        for input_path in &input_paths {
            let lstat = match fs::symlink_metadata(input_path) {
                Ok(m) => m,
                Err(_) => {
                    results.push(Entry {
                        path: input_path.clone(),
                        size: 0,
                        display_size: 0,
                        is_dir: true,
                        is_error: true,
                    });
                    total_errors += 1;
                    continue;
                }
            };
            if lstat.file_type().is_symlink() {
                if fs::metadata(input_path).is_err() {
                    results.push(Entry {
                        path: input_path.clone(),
                        size: 0,
                        display_size: 0,
                        is_dir: true,
                        is_error: true,
                    });
                    total_errors += 1;
                    continue;
                }
                let meta = fs::metadata(input_path).unwrap();
                if meta.is_dir() {
                    let root_dev = meta.dev();
                    let (size, trav, small, large, _err) = compute_size_recursive(input_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, true);
                    entries_traversed += trav;
                    if small < smallest { smallest = small; }
                    if large > largest { largest = large; }
                    results.push(Entry {
                        path: input_path.clone(),
                        size,
                        display_size: size,
                        is_dir: true,
                        is_error: false,
                    });
                    total_size += size;
                } else {
                    let size = if apparent { lstat.size() } else { lstat.blocks()*512 };
                    entries_traversed += 1;
                    if size < smallest { smallest = size; }
                    if size > largest { largest = size; }
                    results.push(Entry {
                        path: input_path.clone(),
                        size,
                        display_size: size,
                        is_dir: false,
                        is_error: false,
                    });
                    total_size += size;
                }
            } else if lstat.is_dir() {
                let root_dev = lstat.dev();
                let (size, trav, small, large, _err) = compute_size_recursive(input_path, apparent, count_hard_links, stay_on_fs, &ignore_canonical, &input_canonical_set, &mut seen_inodes, root_dev, &mut log_writer, true);
                entries_traversed += trav;
                if small < smallest { smallest = small; }
                if large > largest { largest = large; }
                results.push(Entry {
                    path: input_path.clone(),
                    size,
                    display_size: size,
                    is_dir: true,
                    is_error: false,
                });
                total_size += size;
            } else {
                let dev = lstat.dev();
                let ino = lstat.ino();
                let nlink = lstat.nlink();
                let mut size = if apparent { lstat.size() } else { lstat.blocks()*512 };
                if !count_hard_links && nlink > 1 {
                    if seen_inodes.contains(&(dev, ino)) {
                        size = 0;
                    } else {
                        seen_inodes.insert((dev, ino));
                    }
                }
                entries_traversed += 1;
                if size < smallest { smallest = size; }
                if size > largest { largest = size; }
                results.push(Entry {
                    path: input_path.clone(),
                    size,
                    display_size: size,
                    is_dir: false,
                    is_error: false,
                });
                total_size += size;
            }
        }

        let mut display_results: Vec<Entry> = Vec::new();
        if !no_sort {
            let mut sorted = results.clone();
            sorted.sort_by(|a,b| a.size.cmp(&b.size));
            display_results = sorted;
        } else {
            display_results = results.iter().filter(|e| !e.is_error).cloned().collect();
        }

        for entry in &display_results {
            let formatted = global_args.format.display(entry.display_size);
            let size_colored = format!("\x1b[32m{}\x1b[39m", formatted);
            let path_str = entry.path.display().to_string();
            if entry.is_error {
                println!("{} \x1b[36m{}\x1b[39m  <1 IO Error>", size_colored, path_str);
            } else if entry.is_dir {
                println!("{} \x1b[36m{}\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }

        let print_total = !no_total && input_paths.len() > 1;

        if print_total {
            let total_formatted = global_args.format.display(total_size);
            let size_colored = format!("\x1b[32m{}\x1b[39m", total_formatted);
            if total_errors == 0 {
                println!("{} total", size_colored);
            } else if total_errors == 1 {
                println!("{} total  <1 IO Error>", size_colored);
            } else {
                println!("{} total  <{} IO Errors>", size_colored, total_errors);
            }
        }

        if stats {
            if entries_traversed == 0 {
                smallest = 0;
                largest = 0;
            } else if smallest == u64::MAX {
                smallest = 0;
            }
            eprintln!("Statistics {{ entries_traversed: {}, smallest_file_in_bytes: {}, largest_file_in_bytes: {} }}", entries_traversed, smallest, largest);
        }

        if total_errors > 0 { 1 } else { 0 }
    }
}

fn compute_size_recursive(
    path: &Path,
    apparent: bool,
    count_hard_links: bool,
    stay_on_fs: bool,
    ignore_canonical: &HashSet<PathBuf>,
    input_canonical_set: &HashSet<PathBuf>,
    seen_inodes: &mut HashSet<(u64, u64)>,
    root_dev: u64,
    log_writer: &mut Option<std::fs::File>,
    is_root_dir: bool,
) -> (u64, u64, u64, u64, bool) {
    let lstat = match fs::symlink_metadata(path) {
        Ok(m) => m,
        Err(_) => return (0, 0, u64::MAX, 0, true),
    };
    if lstat.file_type().is_symlink() {
        if let Ok(meta) = fs::metadata(path) {
            if meta.is_dir() {
                let target_path = fs::canonicalize(path).unwrap_or(path.to_path_buf());
                if ignore_canonical.contains(&target_path) && !input_canonical_set.contains(&target_path) {
                    let own_size = if apparent { meta.size() } else { meta.blocks()*512 };
                    return (own_size, 1, own_size, own_size, false);
                }
                let mut total_size = if apparent { meta.size() } else { meta.blocks()*512 };
                let mut entries = 1;
                let mut smallest = total_size;
                let mut largest = total_size;
                let rd = match fs::read_dir(path) {
                    Ok(rd) => rd,
                    Err(_) => return (total_size, entries, smallest, largest, true),
                };
                for entry in rd {
                    if let Ok(e) = entry {
                        let child_path = e.path();
                        let child_lstat = match fs::symlink_metadata(&child_path) {
                            Ok(m) => m,
                            Err(_) => continue,
                        };
                        if child_lstat.file_type().is_symlink() {
                            continue;
                        }
                        if child_lstat.is_dir() {
                            let child_canon = fs::canonicalize(&child_path).unwrap_or(child_path.clone());
                            if ignore_canonical.contains(&child_canon) && !input_canonical_set.contains(&child_canon) {
                                if let Some(ref mut lw) = log_writer {
                                    use std::io::Write;
                                    let now = chrono::Local::now();
                                    let time_str = now.format("%H:%M:%S").to_string();
                                    let msg = format!("{} [DEBUG] (1) dua::common: Ignored \"{}\"\n", time_str, child_path.display());
                                    let _ = lw.write_all(msg.as_bytes());
                                }
                                let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                                total_size += own;
                                entries += 1;
                                if own < smallest { smallest = own; }
                                if own > largest { largest = own; }
                                continue;
                            }
                            if stay_on_fs && child_lstat.dev() != root_dev {
                                let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                                total_size += own;
                                entries += 1;
                                if own < smallest { smallest = own; }
                                if own > largest { largest = own; }
                                continue;
                            }
                        }
                        let (child_size, child_entries, child_small, child_large, _child_err) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, ignore_canonical, input_canonical_set, seen_inodes, root_dev, log_writer, false);
                        total_size += child_size;
                        entries += child_entries;
                        if child_small < smallest { smallest = child_small; }
                        if child_large > largest { largest = child_large; }
                    }
                }
                return (total_size, entries, smallest, largest, false);
            }
        }
        return (0, 0, u64::MAX, 0, true);
    }

    if !lstat.is_dir() {
        let dev = lstat.dev();
        let ino = lstat.ino();
        let nlink = lstat.nlink();
        let size = if apparent { lstat.size() } else { lstat.blocks()*512 };
        if !count_hard_links && nlink > 1 {
            if seen_inodes.contains(&(dev, ino)) {
                return (0, 1, 0, 0, false);
            } else {
                seen_inodes.insert((dev, ino));
            }
        }
        return (size, 1, size, size, false);
    }

    let canon = fs::canonicalize(path).unwrap_or(path.to_path_buf());
    if !is_root_dir && ignore_canonical.contains(&canon) && !input_canonical_set.contains(&canon) {
        if let Some(ref mut lw) = log_writer {
            use std::io::Write;
            let now = chrono::Local::now();
            let time_str = now.format("%H:%M:%S").to_string();
            let msg = format!("{} [DEBUG] (1) dua::common: Ignored \"{}\"\n", time_str, path.display());
            let _ = lw.write_all(msg.as_bytes());
        }
        let own_size = if apparent { lstat.size() } else { lstat.blocks()*512 };
        return (own_size, 1, own_size, own_size, false);
    }

    if !is_root_dir && stay_on_fs && lstat.dev() != root_dev {
        let own_size = if apparent { lstat.size() } else { lstat.blocks()*512 };
        return (own_size, 1, own_size, own_size, false);
    }

    let own_size = if apparent { lstat.size() } else { lstat.blocks()*512 };
    let mut total = own_size;
    let mut entries = 1;
    let mut smallest = own_size;
    let mut largest = own_size;

    let dev = lstat.dev();
    let ino = lstat.ino();
    let nlink = lstat.nlink();
    if !is_root_dir && !count_hard_links && nlink > 1 {
        if seen_inodes.contains(&(dev, ino)) {
            total = 0;
            smallest = u64::MAX;
            largest = 0;
        } else {
            seen_inodes.insert((dev, ino));
        }
    } else if !count_hard_links {
        seen_inodes.insert((dev, ino));
    }

    let rd = match fs::read_dir(path) {
        Ok(rd) => rd,
        Err(_) => return (total, entries, smallest, largest, true),
    };

    for entry in rd {
        if let Ok(e) = entry {
            let child_path = e.path();
            let child_lstat = match fs::symlink_metadata(&child_path) {
                Ok(m) => m,
                Err(_) => continue,
            };
            if child_lstat.file_type().is_symlink() {
                continue;
            }
            if child_lstat.is_dir() {
                let child_canon = fs::canonicalize(&child_path).unwrap_or(child_path.clone());
                if ignore_canonical.contains(&child_canon) && !input_canonical_set.contains(&child_canon) {
                    if let Some(ref mut lw) = log_writer {
                        use std::io::Write;
                        let now = chrono::Local::now();
                        let time_str = now.format("%H:%M:%S").to_string();
                        let msg = format!("{} [DEBUG] (1) dua::common: Ignored \"{}\"\n", time_str, child_path.display());
                        let _ = lw.write_all(msg.as_bytes());
                    }
                    let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                    total += own;
                    entries += 1;
                    if own < smallest { smallest = own; }
                    if own > largest { largest = own; }
                    continue;
                }
                if stay_on_fs && child_lstat.dev() != root_dev {
                    let own = if apparent { child_lstat.size() } else { child_lstat.blocks()*512 };
                    total += own;
                    entries += 1;
                    if own < smallest { smallest = own; }
                    if own > largest { largest = own; }
                    continue;
                }
            }
            let (child_size, child_entries, child_small, child_large, _child_err) = compute_size_recursive(&child_path, apparent, count_hard_links, stay_on_fs, ignore_canonical, input_canonical_set, seen_inodes, root_dev, log_writer, false);
            total += child_size;
            entries += child_entries;
            if child_small < smallest { smallest = child_small; }
            if child_large > largest { largest = child_large; }
        }
    }

    if smallest == u64::MAX {
        smallest = own_size;
    }

    (total, entries, smallest, largest, false)
}
