enum Format {
    Metric,
    Binary,
    Bytes,
    Gb,
    Gib,
    Mb,
    Mib,
}

impl Format {
    fn from_str(s: &str) -> Option<Self> {
        match s {
            "metric" => Some(Format::Metric),
            "binary" => Some(Format::Binary),
            "bytes" => Some(Format::Bytes),
            "gb" => Some(Format::Gb),
            "gib" => Some(Format::Gib),
            "mb" => Some(Format::Mb),
            "mib" => Some(Format::Mib),
            _ => None,
        }
    }
    fn display(&self, bytes: u64) -> String {
        match self {
