# Our earlier patch for is_cwd handling was overwritten? The current code shows path_str = entry.path.display() without is_cwd check. So our earlier patch2 that added is_cwd handling was lost when we restored src/main.rs from scratch? We restored src/main.rs from a backup that didn't have is_cwd handling. We need to re-apply patch for is_cwd.

# Let's check current build_cli and main for is_cwd handling.

grep -n "is_cwd" src/main.rs | head -n 20
# The current src has is_cwd param but display logic doesn't use it (as we saw). We need to fix display logic to use is_cwd.

nl -ba src/main.rs | sed -n '850,885p'

# The display_results loop at line 871 uses entry.path.display() without is_cwd. We need to make it use file_name if is_cwd true.

# Patch that.

python3 << 'PY'
import pathlib
p=pathlib.Path("src/main.rs").read_text()
old="""        for entry in &display_results {
            let formatted = global_args.format.display(entry.display_size);
            let size_colored = format!("\x1b[32m{}\\x1b[39m", formatted);
            let path_str = entry.path.display().to_string();
            if entry.is_error {
                println!("{} \\x1b[36m{}\\x1b[39m  <1 IO Error>", size_colored, path_str);
            } else if entry.is_dir {
                println!("{} \\x1b[36m{}\\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }"""

new="""        for entry in &display_results {
            let formatted = global_args.format.display(entry.display_size);
            let size_colored = format!("\x1b[32m{}\\x1b[39m", formatted);
            let path_str = if is_cwd {
                entry.path.file_name().map(|n| n.to_string_lossy().to_string()).unwrap_or(entry.path.display().to_string())
            } else {
                entry.path.display().to_string()
            };
            if entry.is_error {
                println!("{} \\x1b[36m{}\\x1b[39m  <1 IO Error>", size_colored, path_str);
            } else if entry.is_dir {
                println!("{} \\x1b[36m{}\\x1b[39m", size_colored, path_str);
            } else {
                println!("{} {}", size_colored, path_str);
            }
        }"""

p=p.replace(old,new)
pathlib.Path("src/main.rs").write_text(p)
PY
cargo build --offline 2>&1 | tail -n 5
cd /tmp/ignoreLog && /workspace/target/debug/dua --format bytes aggregate 2>&1 | sed 's/\x1b\[[0-9;]*m//g'
cd /tmp/ignoreLog && /workspace/executable --format bytes aggregate 2>&1 | sed 's/\x1b\[[0-9;]*m//g'
cd /workspace

